/**
 * AppAnimation.ts
 * 動畫效果 陸續加上
 */
import { Node, tween, Tween, TweenEasing, UIOpacity, Vec3 } from 'cc';

export interface ScaleBreathOptions {
    scaleMultiplier?: number; // 放大倍
    durationUp?: number; // 放大時長
    durationDown?: number; // 縮小時常
    easing?: TweenEasing;
}

export interface PopInOptions {
    overshoot?: number; // 彈出時的放大倍數
    settle?: number; // 彈出後的縮小倍數
    durationOvershoot?: number; // 彈出時的放大時長
    durationSettle?: number; // 彈出後的縮小時長
    durationSettleIn?: number; // 縮小到原始大小時常
    easing?: TweenEasing;
}

export interface PopOutOptions {
    settle?: number; // 關閉後的縮小倍數
    durationSettle?: number; // 關閉前的縮小時長
    durationOut?: number; // 關閉時的縮小時長
    easing?: TweenEasing;
}

export interface BounceOptions {
    scaleMultiplier?: number; // 放大倍數
    durationUp?: number; // 放大時長
    durationDown?: number; // 縮小回原始時長
    easing?: TweenEasing;
}

export interface SpinArrowOptions {
    rotationDuration?: number; // 轉圈的時長
    fadeOpacity?: boolean; // 淡出透明度
    fadeDelay?: number; // 淡出前延遲
    fadeDuration?: number; // 淡出時長
    callbackDelay?: number; // callback 延遲
    easing?: TweenEasing;
}

export default class AppAnimation {
    /**
     * 開始呼吸效果
     */
    public static playScaleBreath(node: Node | null | undefined, options: ScaleBreathOptions = {}): void {
        if (!node) return;
        const { scaleMultiplier = 1.05, durationUp = 1, durationDown = 1, easing = 'sineInOut' } = options;

        Tween.stopAllByTarget(node);
        const base = node.scale.clone();
        const peak = new Vec3(base.x * scaleMultiplier, base.y * scaleMultiplier, base.z);

        tween(node).to(durationUp, { scale: peak }, { easing }).to(durationDown, { scale: base }, { easing }).union().repeatForever().start();
    }

    /** 停止呼吸效果 暫時 */
    public static stopScaleBreath(node: Node | null | undefined): void {
        if (!node) return;
        Tween.stopAllByTarget(node);
    }

    /**
     * 彈窗效果
     */
    public static playPopIn(node: Node | null | undefined, baseScale: Vec3, options: PopInOptions = {}, onComplete?: () => void): void {
        if (!node) return;
        const { overshoot = 1.1, settle = 0.9, durationOvershoot = 0.16, durationSettle = 0.16, durationSettleIn = 0.16, easing = 'sineInOut' } = options;

        Tween.stopAllByTarget(node);
        node.setScale(0, 0, baseScale.z);
        tween(node)
            .to(durationOvershoot, { scale: new Vec3(baseScale.x * overshoot, baseScale.y * overshoot, baseScale.z) }, { easing })
            .to(durationSettle, { scale: new Vec3(baseScale.x * settle, baseScale.y * settle, baseScale.z) }, { easing })
            .to(durationSettleIn, { scale: baseScale.clone() }, { easing })
            .call(() => onComplete?.())
            .start();
    }

    /**
     * 彈窗關閉效果
     */
    public static playPopOut(node: Node | null | undefined, baseScale: Vec3, options: PopOutOptions = {}, onComplete?: () => void): void {
        if (!node) return;
        const { settle = 1.1, durationSettle = 0.16, durationOut = 0.16, easing = 'sineInOut' } = options;

        Tween.stopAllByTarget(node);
        tween(node)
            .to(durationSettle, { scale: new Vec3(baseScale.x * settle, baseScale.y * settle, baseScale.z) }, { easing })
            .to(durationOut, { scale: new Vec3(0, 0, baseScale.z) }, { easing })
            .call(() => onComplete?.())
            .start();
    }

    /**
     * 數值變動彈跳效果 從目前大小放大後彈回原本大小
     */
    public static playBounce(node: Node | null | undefined, options: BounceOptions = {}, onComplete?: () => void): void {
        if (!node) return;
        const { scaleMultiplier = 1.3, durationUp = 0.12, durationDown = 0.15, easing = 'backOut' } = options;

        Tween.stopAllByTarget(node);
        const base = node.scale.clone();
        const peak = new Vec3(base.x * scaleMultiplier, base.y * scaleMultiplier, base.z);

        tween(node)
            .to(durationUp, { scale: peak }, { easing })
            .to(durationDown, { scale: base }, { easing: 'sineIn' })
            .call(() => onComplete?.())
            .start();
    }

    /**
     * spin 轉圈的動效
     */
    public static playSpinArrow(node: Node | null | undefined, options: SpinArrowOptions = {}, onComplete?: () => void): Tween<Node> | null {
        if (!node) return null;
        const { rotationDuration = 1, fadeOpacity = false, fadeDelay = 0.8, fadeDuration = 0.2, callbackDelay = 0.9, easing = 'backIn' } = options;

        const subTweens: Tween<any>[] = [
            tween().to(rotationDuration, { eulerAngles: new Vec3(0, 0, -360) }, { easing }),
            tween()
                .delay(callbackDelay)
                .call(() => onComplete?.()),
        ];
        if (fadeOpacity) {
            const uiOpacity = node.getComponent(UIOpacity) || node.addComponent(UIOpacity);
            subTweens.push(tween(uiOpacity).delay(fadeDelay).to(fadeDuration, { opacity: 0 }, { easing: 'sineOut' }));
        }

        return tween(node)
            .parallel(...subTweens)
            .start();
    }
}
